INSERT INTO `goods` VALUES (1,'麻辣盐焗大鸭腿（测试更新）','http://localhost:9090/files/download/1778663083799-2.png',3.59,'这款鸭腿真的超出预期！肉质紧实不柴，卤得特别入味，咸香适中不油腻，连皮都很软糯好吃。分量足、新鲜度高，加热即食很方便，不管下饭还是当零食都合适。包装严实无破损，物流也快，性价比超高，吃完满嘴留香，家人都很喜欢，已经回购好几次，真心推荐！','<p><img src=\"http://localhost:9090/files/download/1778663134484-2.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p>',1066,0,33,'2026-05-13 18:27:23','上架',1,'否','是','否',200,1.00,'2026-12-31 23:59:59',NULL,NULL),(3,'米多奇香米饼1kg休闲零食饼干雪饼 香米饼','http://localhost:9090/files/download/1778668458776-1.png',9.90,'米多奇香米饼不愧是经典零食！打开包装就能闻到浓浓的米香，每一片都咸香酥脆，咬下去“咔嚓”一声，口感超级棒！米饼本身是淡淡的米香原味，不会很甜也不会咸，吃起来负担感很小，家里大人小孩都抢着吃。性价比超高，一大包很实惠，看剧或者当充饥小零食都非常合适。已经回购无数次了，绝对是家中常备！','<p><img src=\"http://localhost:9090/files/download/1778668638670-1.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p>',1382,0,236,'2026-05-13 18:37:23','上架',1,'是','否','否',0,NULL,'2020-01-01 00:00:00',NULL,NULL),(6,'香辣香脆肠玉米热狗肠火腿肠烤肠泡面搭档小香肠办公休闲零食即食 玉米热狗肠','http://localhost:9090/files/download/1778669084179-3.png',4.99,'🔥这款香肠真的太香了！口感Q弹，咬一口满嘴爆汁😋，甜咸比例刚刚好，辣度适中不刺激🌶️，完全符合我的口味期待～包装也很用心，物流超快🚚，店家服务贴心👍，整体体验满分！下次还会回购！✨','<p><img src=\"http://localhost:9090/files/download/1778669135142-3.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p>',558,0,53,'2026-05-13 18:45:43','上架',1,'是','否','否',0,NULL,NULL,NULL,NULL),(7,'得力（deli）连中三元 0.5mm考试可用按动中性笔替芯v1连中三元笔芯 ST头黑色 20支/盒 V77','http://localhost:9090/files/download/1778779393369-4.png',47.20,'✨这款笔芯真的超乎预期！🪄\n书写顺滑，出墨均匀，完全不堵笔，写起来特别流畅～🖋️\n包装严实，快递速度也快，收到时完好无损📦\n配送员态度友好，送货准时，服务满分👏\n用了一整天，字迹清晰，不易断墨，性价比超高🔥\n强烈推荐给需要稳定书写体验的小伙伴！🌟\n整体体验非常满意，值得回购！🎉🎉','<p><img src=\"http://localhost:9090/files/download/1778779447722-4.png\" alt=\"\" data-href=\"\" style=\"width: 50%;\"/></p>',1058,0,61,'2026-05-14 18:34:56','上架',3,'否','否','否',0,NULL,NULL,NULL,NULL),(8,'安踏极钉科技足球鞋男TF碎钉草地飞盘鞋成人大童儿童专业耐磨训练球鞋','http://localhost:9090/files/download/1778779283704-5.png',159.00,'这双鞋子收到后孩子试穿了一下，超出预期，他说很舒服，柔软不卡脚，尺码大小合适，轻便透气，穿着去学校一次，同学都说颜值高，。鞋子做工也不错，安踏大品牌值得信赖。','<p><img src=\"http://localhost:909